import numpy as np, random, json
from collections import deque
random.seed(0)

def neighbors(pos, grid):
    r,c = pos
    H,W = grid.shape
    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
        nr,nc=r+dr,c+dc
        if 0<=nr<H and 0<=nc<W and grid[nr,nc]==0:
            yield (nr,nc)

def bfs_dist(grid, s):
    q=deque([s]); dist={s:0}
    while q:
        u=q.popleft()
        for v in neighbors(u,grid):
            if v not in dist:
                dist[v]=dist[u]+1; q.append(v)
    return dist

def tup(x): return [int(x[0]), int(x[1])]

def sample_instance(path, n_agents):
    grid=np.load(path)
    free=[(int(r),int(c)) for r,c in np.argwhere(grid==0)]
    for _ in range(200):
        starts=random.sample(free, n_agents)
        goals=random.sample(free, n_agents)
        ok=True
        for s,g in zip(starts,goals):
            d=bfs_dist(grid,s)
            if g not in d:
                ok=False; break
        if ok:
            return {'starts':[tup(x) for x in starts],'goals':[tup(x) for x in goals]}
    return None

